const hostDocument = window.parent.document;
const hostWindow = hostDocument.defaultView;
const chatNow = () => hostWindow.SillyTavern.getContext().getCurrentChatId();
async function confirmOpening({chatId, target, text}) {
  if (chatId == null || chatNow() !== chatId) throw new Error('聊天已切换，请重新选择。');
  const first = getChatMessages(0, {include_swipes:true})[0];
  if (!first.swipes?.[target]?.includes('<initvar>')) throw new Error('目标开场缺失');
  await setChatMessages([{message_id:0, swipe_id:target}], {refresh:'affected'});
  if (getChatMessages(0, {include_swipes:true})[0]?.swipe_id !== target) throw new Error('开场跳转未保存');
  const input = hostDocument.querySelector('#send_textarea');
  const setter = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(input), 'value')?.set;
  setter.call(input, text);
  input.dispatchEvent(new hostWindow.Event('input', {bubbles:true}));
  hostWindow.__e2eOpening = '已检票上车 ' + target;
  return '已检票上车。';
}
hostDocument.addEventListener('e2e:opening-confirm', (event) => {
  const packet = event.detail;
  if (!packet || packet.result) return;
  packet.result = confirmOpening(packet);
  packet.result.catch(() => {});
});
hostWindow.__e2eOpeningReady = true;
